?>
<section class="card"><h2><?= e($approved?$bt('2. Entwurf freigegeben'):$bt('2. XML vorbereiten und prüfen')) ?></h2>
<?php if($editable&&!$approved): ?><button form="balance-local-main" name="action" value="tax-filing-balance-generate" formnovalidate class="btn btn-outline theme-secondary"><?= e($bt('XML lokal vorbereiten')) ?></button>
<?php if($filingAvailability['validation_configured']): ?><button form="balance-local-main" name="action" value="tax-filing-validate" formnovalidate class="btn btn-solid theme-primary"><?= e($filing['state']==='validated'?$bt('Erneut prüfen'):$bt('Mit ELSTER prüfen')) ?></button>
<?php else: ?><p role="status"><?= e($bt('Amtliche Prüfung: passende originale ERiC-Laufzeit einrichten.')) ?></p><?php endif ?><?php endif ?>
<?php if($filing['validation']): ?><?php if(($filing['validation']['code']??-1)===0): ?><p><?= e($bt('Amtliche Prüfung bestanden.')) ?></p><?php else: ?><ul><?php foreach(TaxFormPresentation::errors($filing['validation']) as $error): ?><li><?= e($error['text']) ?></li><?php endforeach ?></ul><?php endif ?><?php endif ?>
<?php if($filing['xml_data']): ?><details><summary><?= e($bt('XML und Prüfsumme')) ?></summary><a href="<?= e(url($base+['filing'=>$fid,'tax_filing_download'=>'xml'])) ?>"><?= e(($filing['validation']['code']??null)===0?$bt('Geprüfte E-Bilanz herunterladen'):$bt('Vorbereitete E-Bilanz herunterladen')) ?></a><p><?= e($bt('Prüfsumme:')) ?> <code><?= e($filing['xml_sha256']) ?></code></p></details><?php endif ?>
<?php if($approved): ?><p><?= e($bt('Vorstandsfreigabe liegt für diesen Stand vor.')) ?></p>
<?php elseif($editable&&$filing['state']==='validated'&&BoardAccess::allowed($db,(string)$_SESSION['actor'])): ?><label class="check"><input class="check" type="checkbox" name="reviewed" value="1" form="balance-local-main" required><?= e($bt('Angaben, Kontenzuordnung, Steuerwerte und Anlagen vollständig geprüft.')) ?></label><button form="balance-local-main" name="action" value="tax-filing-balance-approve" formnovalidate class="btn btn-solid theme-primary"><?= e($filingProduction?$bt('Entwurf für die Produktion freigeben'):$bt('Entwurf für den Test freigeben')) ?></button>
<?php elseif($filing['state']==='validated'): ?><p><?= e($bt('Vorstand muss den geprüften Entwurf freigeben.')) ?></p><?php endif ?></section>
<?php if($editable&&$filing['state']==='validated'&&$approved): ?><p><?=e($bt('Die Abgabe benötigt eine eigene ausdrückliche Bestätigung.'))?></p><button form="balance-local-main" name="action" value="balance-local-send-review" class="btn btn-outline" formnovalidate><?=e($bt('Weiter zur ausdrücklichen Abgabefreigabe'))?></button><?php endif ?>
<?php if($editable&&$filing['state']==='validated'&&$approved&&($balanceLocalState['send_review']??false)): ?><section class="card"><h2><?= e($filingProduction?$bt('3. E-Bilanz senden'):$bt('3. Test senden')) ?></h2>
